import type { Plugin } from 'vite';

/**
 * esbuild-plugin-react-jsx — handles both TypeScript stripping AND JSX transform.
 *
 * Replaces @vitejs/plugin-react for the vitest environment because oxc
 * (used by @vitejs/plugin-react on Vite 6+) cannot parse TypeScript
 * `import type` or `typeof` in type positions, even in .test.tsx files.
 * esbuild correctly handles both in a single transform pass.
 */
function esbuildPluginReactJsx(): Plugin {
  return {
    name: 'esbuild-react-jsx',
    enforce: 'pre' as const,
    transform(code, id) {
      if (!id.match(/\.(tsx?|jsx?)$/)) return null;
      // Use esbuild to strip types and transform JSX in one pass
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const esbuild = require('esbuild') as typeof import('esbuild');
      const result = esbuild.transformSync(code, {
        loader: id.endsWith('x') ? 'tsx' : 'ts',
        jsx: 'automatic',
        jsxImportSource: 'react',
        target: 'node18',
        sourcemap: false,
        sourcesContent: false,
      });
      return { code: result.code, map: result.map ?? undefined };
    },
  };
}

export default defineConfig({
  plugins: [esbuildPluginReactJsx()],
