import { defineConfig } from 'vitest/config';
import react from '@vitejs/plugin-react';
import { resolve } from 'node:path';
import type { Plugin } from 'vite';

/**
 * esbuild-strip-types — strips TypeScript `import type` / `export type` / inline
 * type modifiers so that the downstream @vitejs/plugin-react oxc parser can handle
 * the file without choking on the `type` keyword.
 *
 * Runs as a PRE-transform so its output feeds directly into the JSX transform.
 * This lets us keep @vitejs/plugin-react (which handles JSX well) while fixing
 * the `import type` / `typeof` parse failure using esbuild's TypeScript support.
 */
function esbuildStripTypes(): Plugin {
  return {
    name: 'esbuild-strip-types',
    enforce: 'pre' as const,
    async transform(code, id) {
      if (!id.match(/\.(tsx?|jsx?)$/)) return null;
      // eslint-disable-next-line @typescript-eslint/no-require-imports
      const esbuild = require('esbuild') as typeof import('esbuild');
      const result = await esbuild.transform(code, {
        loader: id.endsWith('x') ? 'tsx' : 'ts',
        // 'preserve' keeps JSX as-is; we only want esbuild to strip TypeScript
        jsx: 'preserve',
        target: 'node18',
        sourcemap: false,
        sourcesContent: false,
        // Strip type-only imports/exports so oxc never sees them
        drop: [],
        // Use legal comments removal to clean up leftover //@__PURE__ etc
        legalComments: 'none',
      });
      return { code: result.code, map: result.map ?? undefined };
    },
  };
}

